import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Activity, ArrowDown, ArrowUp, ArrowUpRight, Bell, BookOpen, CheckCircle2, ChevronDown, ChevronRight, Clock3, ExternalLink, FileEdit, FileText, FolderTree, Image, Layers3, Megaphone, Minus, MonitorPlay, Music, Pencil, Plus, Quote, Search, Send, Shield, Trash2, Type, Users, Video, X } from 'lucide-react';
import { type ReactNode, useState } from 'react';
import { Link, NavLink, useParams, useSearchParams } from 'react-router-dom';
import { apiDelete, apiGet, apiPatch, apiPost, apiUpload } from '../api/client';
import { PageHeader } from '../components/layout';
import { ErrorState, PageSkeleton } from '../components/states';
import { Badge, Button, Card, EmptyState, SectionHeading } from '../components/ui';
import type { LessonContentType } from '../types';

interface AdminSummary { users: number; activeUsers: number; courses: number; publishedCourses: number; lessons: number; vocabulary: number; hskLevels: number; exercises: number; notifications: number; revenue: number }
interface AdminUser { id: string; name: string; email: string; avatarUrl?: string | null; status: 'ACTIVE' | 'DISABLED' | 'PENDING'; createdAt: string; lastLoginAt?: string | null; level?: string | null; roles: string[]; notificationCount: number; courseCount: number }
interface AdminUsersResponse { items: AdminUser[]; pagination: { page: number; limit: number; total: number; totalPages: number } }
interface AdminCourse { id: string; slug: string; title: string; subtitle: string; summary?: string; description: string; coverColor: string; coverImageUrl?: string | null; coverImageAlt?: string | null; demoVideoUrl?: string | null; demoVideoThumbnailUrl?: string | null; durationHours: number; status: 'DRAFT' | 'PUBLISHED' | 'ARCHIVED'; createdAt: string; updatedAt: string; level: { code: string; name: string }; category: { slug: string; name: string }; moduleCount: number; lessonCount: number; learnerCount: number }
interface AdminCoursesResponse { items: AdminCourse[]; pagination: { page: number; limit: number; total: number; totalPages: number } }
interface AdminLessonNode { id: string; slug: string; title: string; summary: string; durationMinutes: number; sortOrder: number; status: string; exerciseCount: number; vocabularyCount: number; contentCount: number }
interface AdminLessonBranch { id: string; title: string; subtitle?: string | null; sortOrder: number; lessons: AdminLessonNode[] }
interface AdminLessonCourse { course: { id: string; slug: string; title: string; level: string; levelCode: string }; moduleCount: number; lessonCount: number; branches: AdminLessonBranch[] }
interface AdminLessonsResponse { items: AdminLessonCourse[]; totalCourses: number; totalLessons: number }
interface ModuleForm { courseId: string; title: string; subtitle: string }
interface LessonForm { moduleId: string; slug: string; title: string; summary: string; durationMinutes: number; status: 'DRAFT' | 'PUBLISHED' | 'ARCHIVED' }
interface AdminHskLevel { code: string; name: string; description: string; vocabularyCount: number; courseCount: number; exerciseCount: number; skillBreakdown: { listening: number; speaking: number; reading: number; writing: number } }
interface AdminNotification { id: string; title: string; body: string; type: string; createdAt: string; user: { name: string; email: string } }
interface AdminNotificationsResponse { items: AdminNotification[]; total: number }
interface AdminContentBlock { id: string; lessonId: string; type: LessonContentType; title?: string | null; body?: string | null; assetUrl?: string | null; thumbnailUrl?: string | null; mimeType?: string | null; durationSeconds?: number | null; altText?: string | null; caption?: string | null; sortOrder: number }
interface AdminLessonContentResponse { id: string; title: string; summary: string; durationMinutes: number; status: string; module: { course: { id: string; slug: string; title: string; coverColor: string } }; contentBlocks: AdminContentBlock[]; sections: Array<{ id: string; title: string; body: string; type: string }> }
interface ContentBlockForm { type: LessonContentType; title: string; body: string; assetUrl: string; thumbnailUrl: string; mimeType: string; durationSeconds: number; altText: string; caption: string }

const blankContentBlock: ContentBlockForm = { type: 'TEXT', title: '', body: '', assetUrl: '', thumbnailUrl: '', mimeType: '', durationSeconds: 0, altText: '', caption: '' };
const contentTypeMeta: Record<LessonContentType, { label: string; helper: string }> = {
  TEXT: { label: 'Văn bản', helper: 'Giải thích, hội thoại, hướng dẫn hoặc ghi chú.' },
  IMAGE: { label: 'Hình ảnh', helper: 'Ảnh minh họa, sơ đồ, flashcard hoặc infographic.' },
  VIDEO: { label: 'Video', helper: 'Video MP4/WebM hoặc liên kết YouTube/Vimeo.' },
  AUDIO: { label: 'Audio', helper: 'File nghe MP3/WAV/OGG cho phát âm và hội thoại.' },
  FILE: { label: 'Tài liệu', helper: 'PDF, Word, PowerPoint, Excel hoặc file văn bản.' },
  EMBED: { label: 'Embed / iframe', helper: 'Nội dung nhúng từ công cụ học tập bên ngoài.' },
  CALLOUT: { label: 'Ghi chú nổi bật', helper: 'Mẹo học, cảnh báo lỗi thường gặp hoặc mục tiêu.' },
  DIVIDER: { label: 'Phân cách', helper: 'Tạo khoảng nghỉ giữa các phần nội dung.' },
};

const adminLinks = [
  { label: 'Tổng quan', to: '/admin', icon: Activity },
  { label: 'Người dùng', to: '/admin/users', icon: Users },
  { label: 'Khóa học', to: '/admin/courses', icon: BookOpen },
  { label: 'Bài học', to: '/admin/lessons', icon: FileEdit },
  { label: 'Kho HSK', to: '/admin/vocabulary', icon: Layers3 },
  { label: 'Thông báo', to: '/admin/notifications', icon: Bell },
];

function AdminNav() {
  return <nav className="admin-console-nav" aria-label="Khu vực quản trị">{adminLinks.map(({ label, to, icon: Icon }) => <NavLink key={to} to={to} className={({ isActive }) => isActive ? 'active' : ''}><Icon size={15} /> {label}</NavLink>)}</nav>;
}

function AdminStat({ icon, label, value, helper, tone }: { icon: ReactNode; label: string; value: string; helper: string; tone: string }) {
  return <Card className="stat-card"><span className={`stat-icon stat-${tone}`}>{icon}</span><div><span className="stat-label">{label}</span><strong className="stat-value">{value}</strong><small className="stat-helper">{helper}</small></div></Card>;
}

function formatDate(value?: string | null) { return value ? new Intl.DateTimeFormat('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(value)) : 'Chưa có'; }
function statusLabel(status: string) { return status === 'ACTIVE' ? 'Đang hoạt động' : status === 'DISABLED' ? 'Đã khóa' : status === 'PENDING' ? 'Chờ duyệt' : status === 'PUBLISHED' ? 'Đã xuất bản' : status === 'ARCHIVED' ? 'Đã lưu trữ' : 'Bản nháp'; }

export function AdminPage() {
  const summaryQuery = useQuery({ queryKey: ['admin-summary'], queryFn: () => apiGet<AdminSummary>('/admin/summary') });
  const hskQuery = useQuery({ queryKey: ['admin-hsk'], queryFn: () => apiGet<AdminHskLevel[]>('/admin/hsk') });
  if (summaryQuery.isLoading) return <PageSkeleton />;
  if (summaryQuery.isError || !summaryQuery.data) return <ErrorState message="Không thể tải dữ liệu quản trị." retry={() => void summaryQuery.refetch()} />;
  const data = summaryQuery.data;
  return <div className="page-stack admin-page"><AdminNav /><PageHeader eyebrow="ADMIN CONSOLE" title="Vận hành HanLearn" description="Quản lý người dùng, nội dung HSK và các thông báo trong một không gian rõ ràng." action={<Button variant="secondary" onClick={() => window.print()}><Activity size={16} /> Xuất báo cáo</Button>} /><div className="stats-grid admin-stats"><AdminStat icon={<Users size={20} />} label="Tổng người dùng" value={data.users.toLocaleString('vi-VN')} helper={`${data.activeUsers.toLocaleString('vi-VN')} hoạt động 30 ngày`} tone="purple" /><AdminStat icon={<BookOpen size={20} />} label="Khóa học xuất bản" value={`${data.publishedCourses}/${data.courses}`} helper={`${data.lessons} bài học`} tone="red" /><AdminStat icon={<Layers3 size={20} />} label="Từ vựng tiếng Trung" value={data.vocabulary.toLocaleString('vi-VN')} helper={`HSK 1 → HSK 6`} tone="orange" /><AdminStat icon={<Activity size={20} />} label="Bài luyện kỹ năng" value={data.exercises.toLocaleString('vi-VN')} helper={`${data.notifications} thông báo đã gửi`} tone="green" /></div><div className="admin-main-grid"><Card className="admin-overview-chart"><div className="chart-heading"><div><div className="card-overline">TRUNG TÂM VẬN HÀNH</div><h2>Thao tác nhanh</h2></div><Shield size={20} color="var(--primary)" /></div><div className="admin-command-grid"><Link to="/admin/courses"><BookOpen size={18} /><span><strong>Tạo khóa học</strong><small>Thêm lộ trình mới theo cấp HSK</small></span><ArrowUpRight size={15} /></Link><Link to="/admin/users"><Users size={18} /><span><strong>Kiểm tra người dùng</strong><small>Phân quyền và trạng thái tài khoản</small></span><ArrowUpRight size={15} /></Link><Link to="/admin/notifications"><Megaphone size={18} /><span><strong>Gửi thông báo</strong><small>Nhắc học tập hoặc thông báo hệ thống</small></span><ArrowUpRight size={15} /></Link><Link to="/admin/vocabulary"><Layers3 size={18} /><span><strong>Kiểm tra kho HSK</strong><small>Đối chiếu từ vựng và bài luyện</small></span><ArrowUpRight size={15} /></Link></div></Card><Card className="admin-content-card"><div className="card-overline">NỘI DUNG HSK</div><h2>Phân bổ theo cấp độ</h2>{hskQuery.isLoading ? <div className="admin-mini-loading">Đang tải dữ liệu…</div> : hskQuery.isError ? <p className="muted-copy">Không thể tải phân bổ HSK.</p> : <div className="admin-hsk-mini-list">{hskQuery.data?.map((level) => <div key={level.code}><span><Badge tone={level.code === 'HSK1' || level.code === 'HSK2' ? 'red' : level.code === 'HSK3' || level.code === 'HSK4' ? 'orange' : 'purple'}>{level.name}</Badge><small>{level.exerciseCount} bài luyện</small></span><strong>{level.vocabularyCount}</strong></div>)}</div>}<Link className="button button-secondary button-sm" to="/admin/vocabulary">Mở kho HSK <ArrowUpRight size={14} /></Link></Card></div><section><SectionHeading eyebrow="QUẢN TRỊ NHANH" title="Các khu vực chính" /><div className="admin-shortcuts">{adminLinks.slice(1).map(({ label, to, icon: Icon }) => <Link to={to} key={to}><span className="shortcut-icon purple"><Icon size={19} /></span><div><strong>{label}</strong><small>{label === 'Người dùng' ? 'Tài khoản và phân quyền' : label === 'Khóa học' ? 'Danh mục và trạng thái xuất bản' : label === 'Bài học' ? 'Bài học và bài luyện HSK' : label === 'Kho HSK' ? 'Từ vựng theo cấp độ' : 'Gửi và theo dõi thông báo'}</small></div><ArrowUpRight size={16} /></Link>)}</div></section></div>;
}

export function AdminUsersPage() {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [role, setRole] = useState('');
  const [status, setStatus] = useState('');
  const query = useQuery({ queryKey: ['admin-users', search, role, status], queryFn: () => apiGet<AdminUsersResponse>('/admin/users', { search: search || undefined, role: role || undefined, status: status || undefined, limit: 50 }) });
  const statusMutation = useMutation({ mutationFn: ({ id, nextStatus }: { id: string; nextStatus: AdminUser['status'] }) => apiPatch(`/admin/users/${id}/status`, { status: nextStatus }), onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ['admin-users'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const roleMutation = useMutation({ mutationFn: ({ id, nextRole }: { id: string; nextRole: string }) => apiPatch(`/admin/users/${id}/role`, { role: nextRole }), onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ['admin-users'] }); } });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải danh sách người dùng." retry={() => void query.refetch()} />;
  return <div className="page-stack admin-users-page"><AdminNav /><PageHeader eyebrow="QUẢN TRỊ NGƯỜI DÙNG" title="Người dùng" description="Tìm kiếm, phân quyền và theo dõi trạng thái tài khoản." action={<Badge tone="purple">{query.data.pagination.total} tài khoản</Badge>} /><div className="admin-toolbar"><div className="catalog-search"><Search size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Tìm theo tên hoặc email…" aria-label="Tìm người dùng" /></div><select value={role} onChange={(event) => setRole(event.target.value)} aria-label="Lọc theo vai trò"><option value="">Tất cả vai trò</option><option value="student">Học viên</option><option value="teacher">Giáo viên</option><option value="admin">Quản trị viên</option></select><select value={status} onChange={(event) => setStatus(event.target.value)} aria-label="Lọc theo trạng thái"><option value="">Tất cả trạng thái</option><option value="ACTIVE">Đang hoạt động</option><option value="DISABLED">Đã khóa</option><option value="PENDING">Chờ duyệt</option></select></div>{statusMutation.isSuccess && <div className="admin-feedback success"><CheckCircle2 size={16} /> Đã cập nhật trạng thái người dùng.</div>}<Card className="admin-table-card"><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>NGƯỜI DÙNG</th><th>VAI TRÒ</th><th>TRÌNH ĐỘ</th><th>HOẠT ĐỘNG</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>{query.data.items.map((user) => <tr key={user.id}><td><span className="user-table-name"><span className="avatar avatar-small">{user.name.slice(0, 2).toUpperCase()}</span><span><strong>{user.name}</strong><small>{user.email}</small></span></span></td><td><select className="admin-inline-select" value={user.roles[0] ?? 'student'} onChange={(event) => roleMutation.mutate({ id: user.id, nextRole: event.target.value })} aria-label={`Vai trò của ${user.name}`}><option value="student">Học viên</option><option value="teacher">Giáo viên</option><option value="admin">Quản trị viên</option></select></td><td>{user.level ?? '—'}</td><td><span className="admin-table-muted">Đăng nhập: {formatDate(user.lastLoginAt)}<br />{user.courseCount} khóa học</span></td><td><Badge tone={user.status === 'ACTIVE' ? 'green' : user.status === 'DISABLED' ? 'red' : 'orange'}>{statusLabel(user.status)}</Badge></td><td><Button variant="secondary" size="sm" loading={statusMutation.isPending} onClick={() => statusMutation.mutate({ id: user.id, nextStatus: user.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE' })}>{user.status === 'ACTIVE' ? 'Khóa' : 'Mở khóa'}</Button></td></tr>)}</tbody></table></div>{query.data.items.length === 0 && <EmptyState icon="⌕" title="Không có người dùng phù hợp" description="Thử thay đổi từ khóa hoặc bộ lọc." />}</Card></div>;
}

interface CourseForm { title: string; slug: string; summary: string; description: string; levelCode: string; categorySlug: string; durationHours: number; coverColor: string; coverImageUrl: string; coverImageAlt: string; demoVideoUrl: string; demoVideoThumbnailUrl: string; status: 'DRAFT' | 'PUBLISHED' | 'ARCHIVED' }
type CourseMediaField = 'coverImageUrl' | 'demoVideoUrl' | 'demoVideoThumbnailUrl';
const blankCourse: CourseForm = { title: '', slug: '', summary: '', description: '', levelCode: 'HSK1', categorySlug: 'exam-prep', durationHours: 24, coverColor: '#E53935', coverImageUrl: '', coverImageAlt: '', demoVideoUrl: '', demoVideoThumbnailUrl: '', status: 'DRAFT' };

export function AdminCoursesPage() {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);
  const [form, setForm] = useState<CourseForm>(blankCourse);
  const query = useQuery({ queryKey: ['admin-courses', search, status], queryFn: () => apiGet<AdminCoursesResponse>('/admin/courses', { search: search || undefined, status: status || undefined, limit: 100 }) });
  const createMutation = useMutation({ mutationFn: (input: CourseForm) => apiPost<AdminCourse>('/admin/courses', input), onSuccess: () => { setForm(blankCourse); setShowForm(false); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const updateMutation = useMutation({ mutationFn: ({ id, input }: { id: string; input: CourseForm }) => apiPatch<AdminCourse>(`/admin/courses/${id}`, input), onSuccess: () => { setForm(blankCourse); setEditingCourseId(null); setShowForm(false); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const statusMutation = useMutation({ mutationFn: ({ id, nextStatus }: { id: string; nextStatus: CourseForm['status'] }) => apiPatch(`/admin/courses/${id}`, { status: nextStatus }), onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const mediaUploadMutation = useMutation({ mutationFn: ({ file, field }: { file: File; field: CourseMediaField }) => apiUpload<{ url: string; mimeType: string }>('/media/upload', file).then((uploaded) => ({ ...uploaded, field })), onSuccess: (uploaded) => setForm((current) => ({ ...current, [uploaded.field]: uploaded.url })), });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải danh sách khóa học." retry={() => void query.refetch()} />;
  const setField = <K extends keyof CourseForm>(key: K, value: CourseForm[K]) => setForm((current) => ({ ...current, [key]: value }));
  const uploadCourseMedia = (field: CourseMediaField, file?: File) => { if (file) mediaUploadMutation.mutate({ file, field }); };
  const openCreate = () => { setEditingCourseId(null); setForm(blankCourse); setShowForm(true); };
  const openEdit = (course: AdminCourse) => { setEditingCourseId(course.id); setForm({ title: course.title, slug: course.slug, summary: course.summary ?? course.subtitle, description: course.description, levelCode: course.level.code, categorySlug: course.category.slug, durationHours: course.durationHours, coverColor: course.coverColor, coverImageUrl: course.coverImageUrl ?? '', coverImageAlt: course.coverImageAlt ?? '', demoVideoUrl: course.demoVideoUrl ?? '', demoVideoThumbnailUrl: course.demoVideoThumbnailUrl ?? '', status: course.status }); setShowForm(true); };
  const closeForm = () => { setEditingCourseId(null); setForm(blankCourse); setShowForm(false); };
  const isSaving = createMutation.isPending || updateMutation.isPending;
  const saveError = createMutation.isError || updateMutation.isError;
  return <div className="page-stack admin-courses-page"><AdminNav /><PageHeader eyebrow="QUẢN TRỊ NỘI DUNG" title="Khóa học" description="Tạo và chỉnh sửa lộ trình, kiểm soát cấp HSK và trạng thái xuất bản." action={<Button onClick={() => showForm ? closeForm() : openCreate()}>{showForm ? <X size={16} /> : <Plus size={16} />} {showForm ? 'Đóng form' : 'Tạo khóa học'}</Button>} />{showForm && <Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">{editingCourseId ? 'CHỈNH SỬA KHÓA HỌC' : 'KHÓA HỌC MỚI'}</div><h2>{editingCourseId ? 'Cập nhật lộ trình' : 'Tạo lộ trình HSK'}</h2></div><Badge tone={form.status === 'PUBLISHED' ? 'green' : form.status === 'ARCHIVED' ? 'purple' : 'orange'}>{statusLabel(form.status)}</Badge></div><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); if (editingCourseId) updateMutation.mutate({ id: editingCourseId, input: form }); else createMutation.mutate(form); }}><label>Tên khóa học<input required value={form.title} onChange={(event) => setField('title', event.target.value)} placeholder="Ví dụ: HSK 3 · Giao tiếp" /></label><label>Slug<input required value={form.slug} onChange={(event) => setField('slug', event.target.value)} placeholder="hsk-3-giao-tiep" /></label><label className="admin-field-wide">Tóm tắt khóa học<textarea required minLength={10} maxLength={280} rows={2} value={form.summary} onChange={(event) => setField('summary', event.target.value)} placeholder="Một câu ngắn giúp người học hiểu khóa học này dành cho ai và đạt được gì" /></label><label className="admin-field-wide">Ảnh đại diện khóa học<input required value={form.coverImageUrl} onChange={(event) => setField('coverImageUrl', event.target.value)} placeholder="/api/v1/media/files/... hoặc URL CDN" /><small className="admin-field-help">Ảnh JPG, PNG, WEBP hoặc GIF; có thể dán URL hoặc tải từ máy.</small><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={(event) => { uploadCourseMedia('coverImageUrl', event.target.files?.[0]); event.currentTarget.value = ''; }} disabled={mediaUploadMutation.isPending} /></label><label>Văn bản thay thế cho ảnh<input required value={form.coverImageAlt} onChange={(event) => setField('coverImageAlt', event.target.value)} placeholder="Ví dụ: Học tiếng Trung qua giao tiếp đời sống" /></label><label className="admin-field-wide">Video demo khóa học<input required value={form.demoVideoUrl} onChange={(event) => setField('demoVideoUrl', event.target.value)} placeholder="YouTube, Vimeo hoặc URL file MP4/WebM" /><small className="admin-field-help">Video giới thiệu nội dung, cách học và trải nghiệm khóa học.</small><input type="file" accept="video/mp4,video/webm,video/quicktime" onChange={(event) => { uploadCourseMedia('demoVideoUrl', event.target.files?.[0]); event.currentTarget.value = ''; }} disabled={mediaUploadMutation.isPending} /></label><label>Ảnh thumbnail video<input value={form.demoVideoThumbnailUrl} onChange={(event) => setField('demoVideoThumbnailUrl', event.target.value)} placeholder="URL ảnh thumbnail tùy chọn" /></label><label>Cấp độ<select value={form.levelCode} onChange={(event) => setField('levelCode', event.target.value)}>{[1, 2, 3, 4, 5, 6].map((level) => <option key={level} value={`HSK${level}`}>HSK {level}</option>)}</select></label><label>Danh mục<select value={form.categorySlug} onChange={(event) => setField('categorySlug', event.target.value)}><option value="foundation">Nền tảng</option><option value="exam-prep">Luyện thi HSK</option></select></label><label>Thời lượng (giờ)<input type="number" min="1" max="500" value={form.durationHours} onChange={(event) => setField('durationHours', Number(event.target.value))} /></label><label className="admin-field-wide">Mô tả khóa học<textarea required minLength={10} maxLength={1000} value={form.description} onChange={(event) => setField('description', event.target.value)} rows={4} placeholder="Mục tiêu, nội dung chính và kết quả đầu ra của khóa học" /></label><label>Màu nhận diện<input type="color" value={form.coverColor} onChange={(event) => setField('coverColor', event.target.value)} /></label><label>Trạng thái<select value={form.status} onChange={(event) => setField('status', event.target.value as CourseForm['status'])}><option value="DRAFT">Bản nháp</option><option value="PUBLISHED">Xuất bản</option><option value="ARCHIVED">Lưu trữ</option></select></label><div className="admin-form-actions"><Button type="submit" loading={isSaving}>{editingCourseId ? <Pencil size={16} /> : <Plus size={16} />} {editingCourseId ? 'Lưu thay đổi' : 'Tạo khóa học'}</Button>{saveError && <span className="admin-feedback error">Không thể lưu khóa học. Kiểm tra slug và dữ liệu nhập.</span>}</div></form></Card>}<div className="admin-toolbar"><div className="catalog-search"><Search size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Tìm tên hoặc slug khóa học…" aria-label="Tìm khóa học" /></div><select value={status} onChange={(event) => setStatus(event.target.value)} aria-label="Lọc trạng thái khóa học"><option value="">Mọi trạng thái</option><option value="PUBLISHED">Đã xuất bản</option><option value="DRAFT">Bản nháp</option><option value="ARCHIVED">Đã lưu trữ</option></select></div><Card className="admin-table-card"><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>KHÓA HỌC</th><th>CẤP ĐỘ</th><th>NỘI DUNG</th><th>NGƯỜI HỌC</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>{query.data.items.map((course) => <tr key={course.id}><td><span className="admin-course-cell"><span className="admin-course-color" style={{ background: course.coverColor }} /><span><strong>{course.title}</strong><small>{course.slug}</small></span></span></td><td><Badge tone={course.level.code === 'HSK1' || course.level.code === 'HSK2' ? 'red' : course.level.code === 'HSK3' || course.level.code === 'HSK4' ? 'orange' : 'purple'}>{course.level.name}</Badge></td><td><span className="admin-table-muted">{course.moduleCount} module · {course.lessonCount} bài học<br />{course.durationHours} giờ</span></td><td>{course.learnerCount}</td><td><select className="admin-inline-select" value={course.status} onChange={(event) => statusMutation.mutate({ id: course.id, nextStatus: event.target.value as CourseForm['status'] })} aria-label={`Trạng thái ${course.title}`}><option value="DRAFT">Bản nháp</option><option value="PUBLISHED">Đã xuất bản</option><option value="ARCHIVED">Đã lưu trữ</option></select></td><td><span className="admin-row-actions"><Button variant="secondary" size="sm" onClick={() => openEdit(course)}><Pencil size={14} /> Sửa</Button><Link className="icon-button" to={`/admin/lessons?courseId=${encodeURIComponent(course.id)}`} aria-label={`Quản lý bài học ${course.title}`}><FolderTree size={17} /></Link><Link className="icon-button" to={`/courses/${course.slug}`} aria-label={`Xem ${course.title}`}><ArrowUpRight size={17} /></Link></span></td></tr>)}</tbody></table></div>{query.data.items.length === 0 && <EmptyState icon="⌕" title="Chưa có khóa học" description="Tạo khóa học đầu tiên để bắt đầu xây dựng lộ trình." />}</Card></div>;
}

export function AdminLessonsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedCourseId = searchParams.get('courseId') ?? '';
  const [collapsedBranches, setCollapsedBranches] = useState<Record<string, boolean>>({});
  const coursesQuery = useQuery({ queryKey: ['admin-lesson-courses'], queryFn: () => apiGet<AdminCoursesResponse>('/admin/courses', { limit: 100 }) });
  const query = useQuery({ queryKey: ['admin-lessons-tree', selectedCourseId], queryFn: () => apiGet<AdminLessonsResponse>('/admin/lessons', { courseId: selectedCourseId || undefined, limit: 200 }) });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải danh sách bài học." retry={() => void query.refetch()} />;
  return <div className="page-stack admin-lessons-page"><AdminNav /><PageHeader eyebrow="QUẢN TRỊ NỘI DUNG" title="Cây bài học" description="Quản lý theo cấu trúc cha–con: khóa học → nhánh module → bài học và bài luyện." action={<Badge tone="orange">{query.data.totalCourses} khóa · {query.data.totalLessons} bài</Badge>} /><div className="admin-tree-toolbar"><label>Chọn khóa học<select value={selectedCourseId} onChange={(event) => { const courseId = event.target.value; setCollapsedBranches({}); if (courseId) setSearchParams({ courseId }); else setSearchParams({}); }} aria-label="Lọc cây bài học theo khóa học"><option value="">Tất cả khóa học</option>{coursesQuery.data?.items.map((course) => <option key={course.id} value={course.id}>{course.title} · {course.level.name}</option>)}</select></label><span className="admin-tree-hint"><FolderTree size={15} /> Mỗi nhánh cha chỉ chứa bài học của đúng khóa học</span></div><div className="admin-course-tree">{query.data.items.map((item) => <Card className="admin-course-branch" key={item.course.id}><div className="admin-course-branch-header"><span className="admin-tree-course-icon"><BookOpen size={19} /></span><div><span className="card-overline">{item.course.levelCode}</span><h2>{item.course.title}</h2><p>{item.moduleCount} nhánh cha · {item.lessonCount} bài học</p></div><span className="admin-course-branch-actions"><Link className="button button-secondary button-sm" to={`/admin/lessons?courseId=${encodeURIComponent(item.course.id)}`}><FolderTree size={14} /> Thêm module bài học</Link><Link className="icon-button" to={`/courses/${item.course.slug}`} aria-label={`Xem khóa học ${item.course.title}`}><ArrowUpRight size={17} /></Link></span></div><div className="admin-tree-branches">{item.branches.map((branch) => { const collapsed = Boolean(collapsedBranches[branch.id]); return <div className="admin-tree-branch" key={branch.id}><button type="button" className="admin-tree-branch-toggle" aria-expanded={!collapsed} onClick={() => setCollapsedBranches((current) => ({ ...current, [branch.id]: !current[branch.id] }))}>{collapsed ? <ChevronRight size={16} /> : <ChevronDown size={16} />}<FolderTree size={17} /><span><strong>{branch.title}</strong><small>{branch.subtitle ?? 'Nhánh nội dung của khóa học'}</small></span><Badge tone="purple">{branch.lessons.length} bài</Badge></button>{!collapsed && <div className="admin-tree-lessons">{branch.lessons.map((lesson) => <div className="admin-tree-lesson" key={lesson.id}><span className="admin-tree-connector" aria-hidden="true" /><span className="admin-tree-lesson-icon"><FileEdit size={15} /></span><div className="admin-tree-lesson-copy"><strong>{lesson.title}</strong><small>{String(lesson.sortOrder).padStart(2, '0')} · {lesson.vocabularyCount} từ · {lesson.exerciseCount} hoạt động</small></div><span className="admin-table-muted"><Clock3 size={13} /> {lesson.durationMinutes} phút</span><Badge tone={lesson.status === 'PUBLISHED' ? 'green' : 'orange'}>{statusLabel(lesson.status)}</Badge><Link className="icon-button" to={`/lessons/${lesson.id}`} aria-label={`Mở bài ${lesson.title}`}><ArrowUpRight size={17} /></Link></div>)}</div>}</div>; })}</div></Card>)}{query.data.items.length === 0 && <EmptyState icon="✦" title="Chưa có bài học" description="Tạo khóa học và thêm bài học để bắt đầu xây dựng các nhánh nội dung." />}</div></div>;
}

export function AdminLessonsManagerPage() {
  const queryClient = useQueryClient();
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedCourseId = searchParams.get('courseId') ?? '';
  const [collapsedBranches, setCollapsedBranches] = useState<Record<string, boolean>>({});
  const [editor, setEditor] = useState<'module' | 'lesson' | null>(null);
  const [editingModuleId, setEditingModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [moduleForm, setModuleForm] = useState<ModuleForm>({ courseId: '', title: '', subtitle: '' });
  const [lessonForm, setLessonForm] = useState<LessonForm>({ moduleId: '', slug: '', title: '', summary: '', durationMinutes: 15, status: 'DRAFT' });
  const query = useQuery({ queryKey: ['admin-lessons-tree', selectedCourseId], queryFn: () => apiGet<AdminLessonsResponse>('/admin/lessons', { courseId: selectedCourseId || undefined, limit: 200 }) });
  const moduleMutation = useMutation({ mutationFn: ({ id, form }: { id: string | null; form: ModuleForm }) => id ? apiPatch(`/admin/modules/${id}`, { title: form.title, subtitle: form.subtitle || undefined }) : apiPost(`/admin/courses/${form.courseId}/modules`, { title: form.title, subtitle: form.subtitle || undefined }), onSuccess: () => { setEditor(null); setEditingModuleId(null); void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const lessonMutation = useMutation({ mutationFn: ({ id, form }: { id: string | null; form: LessonForm }) => id ? apiPatch(`/admin/lessons/${id}`, form) : apiPost(`/admin/modules/${form.moduleId}/lessons`, form), onSuccess: () => { setEditor(null); setEditingLessonId(null); void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const moduleDeleteMutation = useMutation({ mutationFn: (id: string) => apiDelete(`/admin/modules/${id}`, { confirm: true }), onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  const lessonDeleteMutation = useMutation({ mutationFn: (id: string) => apiDelete(`/admin/lessons/${id}`, { confirm: true }), onSuccess: () => { void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải danh sách bài học." retry={() => void query.refetch()} />;
  const courseItems = query.data.items;
  const moduleOptions = courseItems.flatMap((item) => item.branches.map((branch) => ({ id: branch.id, title: branch.title, courseTitle: item.course.title })));
  const firstCourseId = selectedCourseId || courseItems[0]?.course.id || '';
  const openNewModule = (courseId = firstCourseId) => { setEditingModuleId(null); setModuleForm({ courseId, title: '', subtitle: '' }); setEditor('module'); };
  const openEditModule = (courseId: string, branch: AdminLessonBranch) => { setEditingModuleId(branch.id); setModuleForm({ courseId, title: branch.title, subtitle: branch.subtitle ?? '' }); setEditor('module'); };
  const openNewLesson = (moduleId = moduleOptions[0]?.id ?? '') => { setEditingLessonId(null); setLessonForm({ moduleId, slug: '', title: '', summary: '', durationMinutes: 15, status: 'DRAFT' }); setEditor('lesson'); };
  const openEditLesson = (branch: AdminLessonBranch, lesson: AdminLessonNode) => { setEditingLessonId(lesson.id); setLessonForm({ moduleId: branch.id, slug: lesson.slug, title: lesson.title, summary: lesson.summary, durationMinutes: lesson.durationMinutes, status: lesson.status as LessonForm['status'] }); setEditor('lesson'); };
  const closeEditor = () => { setEditor(null); setEditingModuleId(null); setEditingLessonId(null); };
  const deleteModule = (branch: AdminLessonBranch) => { if (window.confirm(`Xóa nhánh “${branch.title}” và toàn bộ bài học con?`)) moduleDeleteMutation.mutate(branch.id); };
  const deleteLesson = (lesson: AdminLessonNode) => { if (window.confirm(`Xóa bài học “${lesson.title}” và nội dung luyện tập liên quan?`)) lessonDeleteMutation.mutate(lesson.id); };
  const treeError = moduleMutation.isError || lessonMutation.isError || moduleDeleteMutation.isError || lessonDeleteMutation.isError;
  return <div className="page-stack admin-lessons-page"><AdminNav /><PageHeader eyebrow="QUẢN TRỊ NỘI DUNG" title="Cây bài học" description="Thêm, sửa, xóa nhánh module và bài học trong đúng khóa học." action={<span className="admin-page-actions"><Button onClick={() => openNewModule()} disabled={!courseItems.length}><Plus size={16} /> Thêm module bài học</Button><Button variant="secondary" onClick={() => openNewLesson()} disabled={!moduleOptions.length}><FileEdit size={16} /> Thêm bài học</Button></span>} />{treeError && <div className="admin-feedback error">Không thể hoàn tất thao tác. Hãy kiểm tra dữ liệu và thử lại.</div>}{editor === 'module' && <Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">{editingModuleId ? 'CHỈNH SỬA MODULE' : 'MODULE MỚI'}</div><h2>{editingModuleId ? 'Cập nhật nhánh nội dung' : 'Thêm nhánh cho khóa học'}</h2></div><FolderTree size={21} color="var(--primary)" /></div><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); moduleMutation.mutate({ id: editingModuleId, form: moduleForm }); }}><label>Khóa học<select required disabled={Boolean(editingModuleId)} value={moduleForm.courseId} onChange={(event) => setModuleForm((current) => ({ ...current, courseId: event.target.value }))}><option value="">Chọn khóa học</option>{courseItems.map((item) => <option key={item.course.id} value={item.course.id}>{item.course.title} · {item.course.levelCode}</option>)}</select></label><label>Tên nhánh module<input required value={moduleForm.title} onChange={(event) => setModuleForm((current) => ({ ...current, title: event.target.value }))} placeholder="Ví dụ: Nhánh 3 · Hội thoại" /></label><label className="admin-field-wide">Mô tả nhánh<input value={moduleForm.subtitle} onChange={(event) => setModuleForm((current) => ({ ...current, subtitle: event.target.value }))} placeholder="Mô tả ngắn cho nhóm bài học" /></label><div className="admin-form-actions"><Button type="submit" loading={moduleMutation.isPending}>{editingModuleId ? <Pencil size={16} /> : <Plus size={16} />} {editingModuleId ? 'Lưu module' : 'Tạo module'}</Button><Button type="button" variant="ghost" onClick={closeEditor}>Hủy</Button></div></form></Card>}{editor === 'lesson' && <Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">{editingLessonId ? 'CHỈNH SỬA BÀI HỌC' : 'BÀI HỌC MỚI'}</div><h2>{editingLessonId ? 'Cập nhật bài học' : 'Thêm bài học vào module'}</h2></div><FileEdit size={21} color="var(--primary)" /></div><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); lessonMutation.mutate({ id: editingLessonId, form: lessonForm }); }}><label>Nhánh module<select required value={lessonForm.moduleId} onChange={(event) => setLessonForm((current) => ({ ...current, moduleId: event.target.value }))}><option value="">Chọn nhánh module</option>{moduleOptions.map((module) => <option key={module.id} value={module.id}>{module.courseTitle} · {module.title}</option>)}</select></label><label>Slug bài học<input required value={lessonForm.slug} onChange={(event) => setLessonForm((current) => ({ ...current, slug: event.target.value }))} placeholder="hoi-thoai-co-ban" /></label><label>Tên bài học<input required value={lessonForm.title} onChange={(event) => setLessonForm((current) => ({ ...current, title: event.target.value }))} placeholder="Ví dụ: Hội thoại cơ bản" /></label><label>Thời lượng (phút)<input type="number" min="1" max="600" required value={lessonForm.durationMinutes} onChange={(event) => setLessonForm((current) => ({ ...current, durationMinutes: Number(event.target.value) }))} /></label><label className="admin-field-wide">Tóm tắt<textarea required rows={3} value={lessonForm.summary} onChange={(event) => setLessonForm((current) => ({ ...current, summary: event.target.value }))} placeholder="Mục tiêu và nội dung chính của bài học" /></label><label>Trạng thái<select value={lessonForm.status} onChange={(event) => setLessonForm((current) => ({ ...current, status: event.target.value as LessonForm['status'] }))}><option value="DRAFT">Bản nháp</option><option value="PUBLISHED">Đã xuất bản</option><option value="ARCHIVED">Lưu trữ</option></select></label><div className="admin-form-actions"><Button type="submit" loading={lessonMutation.isPending}>{editingLessonId ? <Pencil size={16} /> : <Plus size={16} />} {editingLessonId ? 'Lưu bài học' : 'Tạo bài học'}</Button><Button type="button" variant="ghost" onClick={closeEditor}>Hủy</Button></div></form></Card>}<div className="admin-tree-toolbar"><label>Chọn khóa học<select value={selectedCourseId} onChange={(event) => { const courseId = event.target.value; setCollapsedBranches({}); closeEditor(); if (courseId) setSearchParams({ courseId }); else setSearchParams({}); }} aria-label="Lọc cây bài học theo khóa học"><option value="">Tất cả khóa học</option>{courseItems.map((item) => <option key={item.course.id} value={item.course.id}>{item.course.title} · {item.course.levelCode}</option>)}</select></label><span className="admin-tree-hint"><FolderTree size={15} /> Khóa học → module cha → bài học con</span></div><div className="admin-course-tree">{courseItems.map((item) => <Card className="admin-course-branch" key={item.course.id}><div className="admin-course-branch-header"><span className="admin-tree-course-icon"><BookOpen size={19} /></span><div><span className="card-overline">{item.course.levelCode}</span><h2>{item.course.title}</h2><p>{item.moduleCount} module · {item.lessonCount} bài học</p></div><span className="admin-course-branch-actions"><Button variant="secondary" size="sm" onClick={() => openNewModule(item.course.id)}><Plus size={14} /> Thêm module bài học</Button><Link className="icon-button" to={`/courses/${item.course.slug}`} aria-label={`Xem khóa học ${item.course.title}`}><ArrowUpRight size={17} /></Link></span></div><div className="admin-tree-branches">{item.branches.map((branch) => { const collapsed = Boolean(collapsedBranches[branch.id]); return <div className="admin-tree-branch" key={branch.id}><div className="admin-tree-branch-heading"><button type="button" className="admin-tree-branch-toggle" aria-expanded={!collapsed} onClick={() => setCollapsedBranches((current) => ({ ...current, [branch.id]: !current[branch.id] }))}>{collapsed ? <ChevronRight size={16} /> : <ChevronDown size={16} />}<FolderTree size={17} /><span><strong>{branch.title}</strong><small>{branch.subtitle ?? 'Nhánh nội dung của khóa học'}</small></span><Badge tone="purple">{branch.lessons.length} bài</Badge></button><span className="admin-tree-node-actions"><Button variant="ghost" size="sm" onClick={() => openNewLesson(branch.id)} aria-label={`Thêm bài học vào ${branch.title}`}><Plus size={14} /></Button><Button variant="ghost" size="sm" onClick={() => openEditModule(item.course.id, branch)} aria-label={`Sửa ${branch.title}`}><Pencil size={14} /></Button><Button variant="danger" size="sm" onClick={() => deleteModule(branch)} loading={moduleDeleteMutation.isPending} aria-label={`Xóa ${branch.title}`}><Trash2 size={14} /></Button></span></div>{!collapsed && <div className="admin-tree-lessons">{branch.lessons.map((lesson) => <div className="admin-tree-lesson" key={lesson.id}><span className="admin-tree-connector" aria-hidden="true" /><span className="admin-tree-lesson-icon"><FileEdit size={15} /></span><div className="admin-tree-lesson-copy"><strong>{lesson.title}</strong><small>{String(lesson.sortOrder).padStart(2, '0')} · {lesson.vocabularyCount} từ · {lesson.exerciseCount} hoạt động</small></div><span className="admin-table-muted"><Clock3 size={13} /> {lesson.durationMinutes} phút</span><Badge tone={lesson.status === 'PUBLISHED' ? 'green' : 'orange'}>{statusLabel(lesson.status)}</Badge><span className="admin-row-actions"><Button variant="ghost" size="sm" onClick={() => openEditLesson(branch, lesson)} aria-label={`Sửa bài ${lesson.title}`}><Pencil size={14} /></Button><Button variant="danger" size="sm" onClick={() => deleteLesson(lesson)} loading={lessonDeleteMutation.isPending} aria-label={`Xóa bài ${lesson.title}`}><Trash2 size={14} /></Button><Link className="icon-button" to={`/lessons/${lesson.id}`} aria-label={`Mở bài ${lesson.title}`}><ArrowUpRight size={17} /></Link></span></div>)}</div>}</div>; })}</div></Card>)}{!courseItems.length && <EmptyState icon="✦" title="Chưa có khóa học" description="Tạo khóa học trước khi thêm module và bài học." />}</div></div>;
}

export function AdminLessonsContentTreePage() {
  const queryClient = useQueryClient();
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedCourseId = searchParams.get('courseId') ?? '';
  const [collapsedBranches, setCollapsedBranches] = useState<Record<string, boolean>>({});
  const [editor, setEditor] = useState<'module' | 'lesson' | null>(null);
  const [editingModuleId, setEditingModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [moduleForm, setModuleForm] = useState<ModuleForm>({ courseId: '', title: '', subtitle: '' });
  const [lessonForm, setLessonForm] = useState<LessonForm>({ moduleId: '', slug: '', title: '', summary: '', durationMinutes: 15, status: 'DRAFT' });
  const query = useQuery({ queryKey: ['admin-lessons-tree', selectedCourseId], queryFn: () => apiGet<AdminLessonsResponse>('/admin/lessons', { courseId: selectedCourseId || undefined, limit: 200 }) });
  const moduleMutation = useMutation({ mutationFn: ({ id, form }: { id: string | null; form: ModuleForm }) => id ? apiPatch(`/admin/modules/${id}`, { title: form.title, subtitle: form.subtitle || undefined }) : apiPost(`/admin/courses/${form.courseId}/modules`, { title: form.title, subtitle: form.subtitle || undefined }), onSuccess: () => { setEditor(null); setEditingModuleId(null); void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); } });
  const lessonMutation = useMutation({ mutationFn: ({ id, form }: { id: string | null; form: LessonForm }) => id ? apiPatch(`/admin/lessons/${id}`, form) : apiPost(`/admin/modules/${form.moduleId}/lessons`, form), onSuccess: () => { setEditor(null); setEditingLessonId(null); void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); void queryClient.invalidateQueries({ queryKey: ['admin-courses'] }); } });
  const moduleDeleteMutation = useMutation({ mutationFn: (id: string) => apiDelete(`/admin/modules/${id}`, { confirm: true }), onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }) });
  const lessonDeleteMutation = useMutation({ mutationFn: (id: string) => apiDelete(`/admin/lessons/${id}`, { confirm: true }), onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }) });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải cây bài học." retry={() => void query.refetch()} />;
  const courseItems = query.data.items;
  const moduleOptions = courseItems.flatMap((item) => item.branches.map((branch) => ({ id: branch.id, title: branch.title, courseTitle: item.course.title })));
  const firstCourseId = selectedCourseId || courseItems[0]?.course.id || '';
  const closeEditor = () => { setEditor(null); setEditingModuleId(null); setEditingLessonId(null); };
  const openNewModule = (courseId = firstCourseId) => { setEditingModuleId(null); setModuleForm({ courseId, title: '', subtitle: '' }); setEditor('module'); };
  const openEditModule = (branch: AdminLessonBranch, courseId: string) => { setEditingModuleId(branch.id); setModuleForm({ courseId, title: branch.title, subtitle: branch.subtitle ?? '' }); setEditor('module'); };
  const openNewLesson = (moduleId = moduleOptions[0]?.id ?? '') => { setEditingLessonId(null); setLessonForm({ moduleId, slug: '', title: '', summary: '', durationMinutes: 15, status: 'DRAFT' }); setEditor('lesson'); };
  const openEditLesson = (branch: AdminLessonBranch, lesson: AdminLessonNode) => { setEditingLessonId(lesson.id); setLessonForm({ moduleId: branch.id, slug: lesson.slug, title: lesson.title, summary: lesson.summary, durationMinutes: lesson.durationMinutes, status: lesson.status as LessonForm['status'] }); setEditor('lesson'); };
  const deleteModule = (branch: AdminLessonBranch) => { if (window.confirm(`Xóa nhánh “${branch.title}” và toàn bộ bài học con?`)) moduleDeleteMutation.mutate(branch.id); };
  const deleteLesson = (lesson: AdminLessonNode) => { if (window.confirm(`Xóa bài học “${lesson.title}” và nội dung liên quan?`)) lessonDeleteMutation.mutate(lesson.id); };
  const treeError = moduleMutation.isError || lessonMutation.isError || moduleDeleteMutation.isError || lessonDeleteMutation.isError;
  return <div className="page-stack admin-lessons-page"><AdminNav /><PageHeader eyebrow="QUẢN TRỊ NỘI DUNG" title="Cây bài học" description="Khóa học → module cha → bài học → nội dung đa phương tiện và bài luyện." action={<span className="admin-page-actions"><Button onClick={() => openNewModule()} disabled={!courseItems.length}><Plus size={16} /> Thêm module bài học</Button><Button variant="secondary" onClick={() => openNewLesson()} disabled={!moduleOptions.length}><FileEdit size={16} /> Thêm bài học</Button></span>} />{treeError && <div className="admin-feedback error">Không thể hoàn tất thao tác. Hãy kiểm tra dữ liệu và thử lại.</div>}{editor === 'module' && <Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">{editingModuleId ? 'CHỈNH SỬA MODULE' : 'MODULE MỚI'}</div><h2>{editingModuleId ? 'Cập nhật nhánh nội dung' : 'Thêm nhánh cho khóa học'}</h2></div><FolderTree size={21} color="var(--primary)" /></div><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); moduleMutation.mutate({ id: editingModuleId, form: moduleForm }); }}><label>Khóa học<select required disabled={Boolean(editingModuleId)} value={moduleForm.courseId} onChange={(event) => setModuleForm((current) => ({ ...current, courseId: event.target.value }))}><option value="">Chọn khóa học</option>{courseItems.map((item) => <option key={item.course.id} value={item.course.id}>{item.course.title} · {item.course.levelCode}</option>)}</select></label><label>Tên module<input required value={moduleForm.title} onChange={(event) => setModuleForm((current) => ({ ...current, title: event.target.value }))} placeholder="Ví dụ: Nhánh 3 · Hội thoại" /></label><label className="admin-field-wide">Mô tả nhánh<input value={moduleForm.subtitle} onChange={(event) => setModuleForm((current) => ({ ...current, subtitle: event.target.value }))} placeholder="Mô tả ngắn cho nhóm bài học" /></label><div className="admin-form-actions"><Button type="submit" loading={moduleMutation.isPending}>{editingModuleId ? <Pencil size={16} /> : <Plus size={16} />} {editingModuleId ? 'Lưu module' : 'Tạo module'}</Button><Button type="button" variant="ghost" onClick={closeEditor}>Hủy</Button></div></form></Card>}{editor === 'lesson' && <Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">{editingLessonId ? 'CHỈNH SỬA BÀI HỌC' : 'BÀI HỌC MỚI'}</div><h2>{editingLessonId ? 'Cập nhật bài học' : 'Thêm bài học vào module'}</h2></div><FileEdit size={21} color="var(--primary)" /></div><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); lessonMutation.mutate({ id: editingLessonId, form: lessonForm }); }}><label>Module<select required value={lessonForm.moduleId} onChange={(event) => setLessonForm((current) => ({ ...current, moduleId: event.target.value }))}><option value="">Chọn module</option>{moduleOptions.map((module) => <option key={module.id} value={module.id}>{module.courseTitle} · {module.title}</option>)}</select></label><label>Slug bài học<input required value={lessonForm.slug} onChange={(event) => setLessonForm((current) => ({ ...current, slug: event.target.value }))} placeholder="hoi-thoai-co-ban" /></label><label>Tên bài học<input required value={lessonForm.title} onChange={(event) => setLessonForm((current) => ({ ...current, title: event.target.value }))} placeholder="Ví dụ: Hội thoại cơ bản" /></label><label>Thời lượng (phút)<input type="number" min="1" max="600" required value={lessonForm.durationMinutes} onChange={(event) => setLessonForm((current) => ({ ...current, durationMinutes: Number(event.target.value) }))} /></label><label className="admin-field-wide">Tóm tắt<textarea required rows={3} value={lessonForm.summary} onChange={(event) => setLessonForm((current) => ({ ...current, summary: event.target.value }))} placeholder="Mục tiêu và nội dung chính của bài học" /></label><label>Trạng thái<select value={lessonForm.status} onChange={(event) => setLessonForm((current) => ({ ...current, status: event.target.value as LessonForm['status'] }))}><option value="DRAFT">Bản nháp</option><option value="PUBLISHED">Xuất bản</option><option value="ARCHIVED">Lưu trữ</option></select></label><div className="admin-form-actions"><Button type="submit" loading={lessonMutation.isPending}>{editingLessonId ? <Pencil size={16} /> : <Plus size={16} />} {editingLessonId ? 'Lưu bài học' : 'Tạo bài học'}</Button><Button type="button" variant="ghost" onClick={closeEditor}>Hủy</Button></div></form></Card>}<div className="admin-tree-toolbar"><label>Chọn khóa học<select value={selectedCourseId} onChange={(event) => { const courseId = event.target.value; setCollapsedBranches({}); closeEditor(); if (courseId) setSearchParams({ courseId }); else setSearchParams({}); }} aria-label="Lọc cây bài học theo khóa học"><option value="">Tất cả khóa học</option>{courseItems.map((item) => <option key={item.course.id} value={item.course.id}>{item.course.title} · {item.course.levelCode}</option>)}</select></label><span className="admin-tree-hint"><FolderTree size={15} /> Mỗi bài học có thể chứa văn bản, ảnh, video, audio, tài liệu và bài luyện.</span></div><div className="admin-course-tree">{courseItems.map((item) => <Card className="admin-course-branch" key={item.course.id}><div className="admin-course-branch-header"><span className="admin-tree-course-icon"><BookOpen size={19} /></span><div><span className="card-overline">{item.course.levelCode}</span><h2>{item.course.title}</h2><p>{item.moduleCount} module · {item.lessonCount} bài học</p></div><span className="admin-course-branch-actions"><Button variant="secondary" size="sm" onClick={() => openNewModule(item.course.id)}><Plus size={14} /> Thêm module bài học</Button><Link className="icon-button" to={`/courses/${item.course.slug}`} aria-label={`Xem khóa học ${item.course.title}`}><ArrowUpRight size={17} /></Link></span></div><div className="admin-tree-branches">{item.branches.map((branch) => { const collapsed = Boolean(collapsedBranches[branch.id]); return <div className="admin-tree-branch" key={branch.id}><div className="admin-tree-branch-heading"><button type="button" className="admin-tree-branch-toggle" aria-expanded={!collapsed} onClick={() => setCollapsedBranches((current) => ({ ...current, [branch.id]: !current[branch.id] }))}>{collapsed ? <ChevronRight size={16} /> : <ChevronDown size={16} />}<FolderTree size={17} /><span><strong>{branch.title}</strong><small>{branch.subtitle ?? 'Nhánh nội dung của khóa học'}</small></span><Badge tone="purple">{branch.lessons.length} bài</Badge></button><span className="admin-tree-node-actions"><Button variant="ghost" size="sm" onClick={() => openNewLesson(branch.id)} aria-label={`Thêm bài học vào ${branch.title}`}><Plus size={14} /></Button><Button variant="ghost" size="sm" onClick={() => openEditModule(branch, item.course.id)} aria-label={`Sửa ${branch.title}`}><Pencil size={14} /></Button><Button variant="danger" size="sm" onClick={() => deleteModule(branch)} loading={moduleDeleteMutation.isPending} aria-label={`Xóa ${branch.title}`}><Trash2 size={14} /></Button></span></div>{!collapsed && <div className="admin-tree-lessons">{branch.lessons.map((lesson) => <div className="admin-tree-lesson" key={lesson.id}><span className="admin-tree-connector" aria-hidden="true" /><span className="admin-tree-lesson-icon"><FileEdit size={15} /></span><div className="admin-tree-lesson-copy"><strong>{lesson.title}</strong><small>{String(lesson.sortOrder).padStart(2, '0')} · {lesson.vocabularyCount} từ · {lesson.exerciseCount} hoạt động · {lesson.contentCount} nội dung</small></div><span className="admin-table-muted"><Clock3 size={13} /> {lesson.durationMinutes} phút</span><Badge tone={lesson.status === 'PUBLISHED' ? 'green' : 'orange'}>{statusLabel(lesson.status)}</Badge><span className="admin-row-actions"><Link className="button button-secondary button-sm" to={`/admin/lessons/${lesson.id}/content`}><FileText size={14} /> Nội dung</Link><Button variant="ghost" size="sm" onClick={() => openEditLesson(branch, lesson)} aria-label={`Sửa bài ${lesson.title}`}><Pencil size={14} /></Button><Button variant="danger" size="sm" onClick={() => deleteLesson(lesson)} loading={lessonDeleteMutation.isPending} aria-label={`Xóa bài ${lesson.title}`}><Trash2 size={14} /></Button><Link className="icon-button" to={`/lessons/${lesson.id}`} aria-label={`Mở bài ${lesson.title}`}><ArrowUpRight size={17} /></Link></span></div>)}</div>}</div>; })}</div></Card>)}{!courseItems.length && <EmptyState icon="✦" title="Chưa có khóa học" description="Tạo khóa học trước khi thêm module và bài học." />}</div></div>;
}

function ContentTypeIcon({ type }: { type: LessonContentType }) {
  if (type === 'TEXT') return <Type size={17} />;
  if (type === 'IMAGE') return <Image size={17} />;
  if (type === 'VIDEO') return <Video size={17} />;
  if (type === 'AUDIO') return <Music size={17} />;
  if (type === 'FILE') return <FileText size={17} />;
  if (type === 'EMBED') return <MonitorPlay size={17} />;
  if (type === 'CALLOUT') return <Quote size={17} />;
  return <Minus size={17} />;
}

export function AdminLessonContentPage() {
  const { id = '' } = useParams();
  const queryClient = useQueryClient();
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<ContentBlockForm>(blankContentBlock);
  const query = useQuery({ queryKey: ['admin-lesson-content', id], queryFn: () => apiGet<AdminLessonContentResponse>(`/admin/lessons/${id}/content`), enabled: Boolean(id) });
  const saveMutation = useMutation({
    mutationFn: ({ blockId, input }: { blockId: string | null; input: Partial<ContentBlockForm> & Pick<ContentBlockForm, 'type'> }) => blockId ? apiPatch(`/admin/content-blocks/${blockId}`, input) : apiPost(`/admin/lessons/${id}/content-blocks`, input),
    onSuccess: () => { setEditingId(null); setForm(blankContentBlock); void queryClient.invalidateQueries({ queryKey: ['admin-lesson-content', id] }); void queryClient.invalidateQueries({ queryKey: ['admin-lessons-tree'] }); },
  });
  const uploadMutation = useMutation({
    mutationFn: (file: File) => apiUpload<{ url: string; name: string; mimeType: string }>('/media/upload', file),
    onSuccess: (uploaded) => setForm((current) => ({ ...current, assetUrl: uploaded.url, mimeType: uploaded.mimeType })),
  });
  const moveMutation = useMutation({
    mutationFn: ({ blockId, direction }: { blockId: string; direction: 'up' | 'down' }) => apiPost(`/admin/content-blocks/${blockId}/move`, { direction }),
    onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['admin-lesson-content', id] }),
  });
  const deleteMutation = useMutation({
    mutationFn: (blockId: string) => apiDelete(`/admin/content-blocks/${blockId}`, { confirm: true }),
    onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['admin-lesson-content', id] }),
  });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải nội dung bài học." retry={() => void query.refetch()} />;
  const lesson = query.data;
  const setField = <K extends keyof ContentBlockForm>(key: K, value: ContentBlockForm[K]) => setForm((current) => ({ ...current, [key]: value }));
  const openNew = () => { setEditingId(null); setForm(blankContentBlock); };
  const openEdit = (block: AdminContentBlock) => setForm({ type: block.type, title: block.title ?? '', body: block.body ?? '', assetUrl: block.assetUrl ?? '', thumbnailUrl: block.thumbnailUrl ?? '', mimeType: block.mimeType ?? '', durationSeconds: block.durationSeconds ?? 0, altText: block.altText ?? '', caption: block.caption ?? '' });
  const editBlock = (block: AdminContentBlock) => { setEditingId(block.id); openEdit(block); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const deleteBlock = (block: AdminContentBlock) => { if (window.confirm(`Xóa nội dung “${block.title || contentTypeMeta[block.type].label}”?`)) deleteMutation.mutate(block.id); };
  const needsAsset = ['IMAGE', 'VIDEO', 'AUDIO', 'FILE', 'EMBED'].includes(form.type);
  const isTextual = ['TEXT', 'CALLOUT'].includes(form.type);
  return <div className="page-stack admin-content-page"><AdminNav /><PageHeader eyebrow="BIÊN TẬP BÀI HỌC" title={lesson.title} description={`${lesson.module.course.title} · ${lesson.summary}`} action={<span className="admin-page-actions"><Link className="button button-secondary button-sm" to={`/admin/lessons?courseId=${encodeURIComponent(lesson.module.course.id)}`}><ArrowUpRight size={15} /> Quay lại cây bài học</Link><Button onClick={openNew}><Plus size={16} /> Thêm nội dung</Button></span>} /><div className="admin-content-layout"><Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">{editingId ? 'CHỈNH SỬA KHỐI NỘI DUNG' : 'KHỐI NỘI DUNG MỚI'}</div><h2>{editingId ? 'Cập nhật nội dung' : 'Thêm vào bài học'}</h2></div><ContentTypeIcon type={form.type} /></div><form className="admin-form-grid" onSubmit={(event) => { event.preventDefault(); saveMutation.mutate({ blockId: editingId, input: { ...form, title: form.title || undefined, body: form.body || undefined, assetUrl: form.assetUrl || undefined, thumbnailUrl: form.thumbnailUrl || undefined, mimeType: form.mimeType || undefined, durationSeconds: form.durationSeconds || undefined, altText: form.altText || undefined, caption: form.caption || undefined } }); }}><label>Loại nội dung<select value={form.type} onChange={(event) => setField('type', event.target.value as LessonContentType)}>{Object.entries(contentTypeMeta).map(([type, meta]) => <option key={type} value={type}>{meta.label}</option>)}</select><small className="admin-field-help">{contentTypeMeta[form.type].helper}</small></label><label>Tiêu đề hiển thị<input value={form.title} onChange={(event) => setField('title', event.target.value)} placeholder="Ví dụ: Hội thoại tại lớp học" /></label>{isTextual && <label className="admin-field-wide">Nội dung<textarea rows={7} value={form.body} onChange={(event) => setField('body', event.target.value)} placeholder="Nhập nội dung bài học, có thể xuống dòng…" /></label>}{needsAsset && <><label className="admin-field-wide">URL media<input required={!form.assetUrl} value={form.assetUrl} onChange={(event) => setField('assetUrl', event.target.value)} placeholder="https://… hoặc /api/v1/media/files/…" /><small className="admin-field-help">Có thể dán URL CDN/YouTube/Vimeo hoặc tải tệp ngay bên dưới.</small></label><label className="admin-field-wide">Tải tệp từ máy<input type="file" accept="image/*,video/*,audio/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt" onChange={(event) => { const file = event.target.files?.[0]; if (file) uploadMutation.mutate(file); event.currentTarget.value = ''; }} disabled={uploadMutation.isPending} /><small className="admin-field-help">Tối đa 100 MB. File được lưu trong volume riêng của production.</small>{uploadMutation.isPending && <small className="admin-field-help">Đang tải tệp lên…</small>}{uploadMutation.isError && <small className="admin-feedback error">Không thể tải tệp. Kiểm tra định dạng và dung lượng.</small>}</label></>}{form.type === 'IMAGE' && <label>Văn bản thay thế<input required value={form.altText} onChange={(event) => setField('altText', event.target.value)} placeholder="Mô tả ảnh cho người dùng dùng trình đọc màn hình" /></label>}{form.type === 'VIDEO' && <label>Ảnh đại diện video<input value={form.thumbnailUrl} onChange={(event) => setField('thumbnailUrl', event.target.value)} placeholder="URL poster tùy chọn" /></label>}{needsAsset && <label>Loại MIME<input value={form.mimeType} onChange={(event) => setField('mimeType', event.target.value)} placeholder="video/mp4 hoặc application/pdf" /></label>}{(form.type === 'VIDEO' || form.type === 'AUDIO') && <label>Thời lượng (giây)<input type="number" min="0" max="86400" value={form.durationSeconds || ''} onChange={(event) => setField('durationSeconds', Number(event.target.value))} /></label>}{form.type !== 'DIVIDER' && <label className="admin-field-wide">Chú thích<textarea rows={2} value={form.caption} onChange={(event) => setField('caption', event.target.value)} placeholder="Ghi chú ngắn hiển thị dưới media (nếu cần)" /></label>}<div className="admin-form-actions"><Button type="submit" loading={saveMutation.isPending} disabled={uploadMutation.isPending}>{editingId ? <Pencil size={16} /> : <Plus size={16} />} {editingId ? 'Lưu nội dung' : 'Thêm nội dung'}</Button>{editingId && <Button type="button" variant="ghost" onClick={openNew}>Hủy sửa</Button>}{saveMutation.isError && <span className="admin-feedback error">Không thể lưu. Kiểm tra nội dung và URL media.</span>}</div></form></Card><Card className="admin-content-list-card"><div className="admin-panel-header"><div><div className="card-overline">DÒNG CHẢY BÀI HỌC</div><h2>{lesson.contentBlocks.length} khối nội dung</h2></div><Badge tone={lesson.status === 'PUBLISHED' ? 'green' : 'orange'}>{statusLabel(lesson.status)}</Badge></div>{lesson.contentBlocks.length ? <div className="admin-content-block-list">{lesson.contentBlocks.map((block, index) => <article className="admin-content-block-row" key={block.id}><span className="admin-content-block-icon"><ContentTypeIcon type={block.type} /></span><div className="admin-content-block-copy"><div><Badge tone="neutral">{contentTypeMeta[block.type].label}</Badge><strong>{block.title || `Khối ${index + 1}`}</strong></div><small>{block.body?.slice(0, 130) || block.assetUrl || contentTypeMeta[block.type].helper}</small>{block.assetUrl && <a href={block.assetUrl} target="_blank" rel="noreferrer"><ExternalLink size={13} /> Mở media</a>}</div><div className="admin-content-block-actions"><Button variant="ghost" size="sm" disabled={index === 0 || moveMutation.isPending} onClick={() => moveMutation.mutate({ blockId: block.id, direction: 'up' })} aria-label="Đưa nội dung lên"><ArrowUp size={15} /></Button><Button variant="ghost" size="sm" disabled={index === lesson.contentBlocks.length - 1 || moveMutation.isPending} onClick={() => moveMutation.mutate({ blockId: block.id, direction: 'down' })} aria-label="Đưa nội dung xuống"><ArrowDown size={15} /></Button><Button variant="secondary" size="sm" onClick={() => editBlock(block)}><Pencil size={14} /> Sửa</Button><Button variant="danger" size="sm" loading={deleteMutation.isPending} onClick={() => deleteBlock(block)}><Trash2 size={14} /></Button></div></article>)}</div> : <EmptyState icon="✦" title="Bài học chưa có nội dung" description="Thêm văn bản, hình ảnh, video, audio hoặc tài liệu để hoàn thiện bài học." action={<Button onClick={openNew}><Plus size={15} /> Thêm khối đầu tiên</Button>} />}</Card></div></div>;
}

export function AdminHskPage() {
  const query = useQuery({ queryKey: ['admin-hsk'], queryFn: () => apiGet<AdminHskLevel[]>('/admin/hsk') });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải kho HSK." retry={() => void query.refetch()} />;
  return <div className="page-stack admin-hsk-page"><AdminNav /><PageHeader eyebrow="KHO TỪ VỰNG & HSK" title="Kho HSK" description="Số liệu thật từ database về từ vựng, khóa học và bài luyện theo từng cấp độ." action={<Badge tone="purple">HSK 1 → HSK 6</Badge>} /><div className="admin-hsk-grid">{query.data.map((level) => <Card className="admin-hsk-card" key={level.code}><div className="admin-panel-header"><div><Badge tone={level.code === 'HSK1' || level.code === 'HSK2' ? 'red' : level.code === 'HSK3' || level.code === 'HSK4' ? 'orange' : 'purple'}>{level.name}</Badge><h2>{level.vocabularyCount.toLocaleString('vi-VN')} từ</h2></div><span className="admin-hsk-symbol">中</span></div><p>{level.description}</p><div className="admin-hsk-metrics"><span><strong>{level.courseCount}</strong><small>khóa học</small></span><span><strong>{level.exerciseCount}</strong><small>bài luyện</small></span></div><div className="admin-hsk-breakdown"><span>Nghe <b>{level.skillBreakdown.listening}</b></span><span>Nói <b>{level.skillBreakdown.speaking}</b></span><span>Đọc <b>{level.skillBreakdown.reading}</b></span><span>Viết <b>{level.skillBreakdown.writing}</b></span></div></Card>)}</div></div>;
}

interface NotificationForm { title: string; body: string; type: string; audience: 'ALL' | 'STUDENTS' | 'TEACHERS' | 'ADMINS' }
const blankNotification: NotificationForm = { title: '', body: '', type: 'ANNOUNCEMENT', audience: 'ALL' };

export function AdminNotificationsPage() {
  const queryClient = useQueryClient();
  const [form, setForm] = useState<NotificationForm>(blankNotification);
  const query = useQuery({ queryKey: ['admin-notifications'], queryFn: () => apiGet<AdminNotificationsResponse>('/admin/notifications') });
  const mutation = useMutation({ mutationFn: (input: NotificationForm) => apiPost<{ sent: number }>('/admin/notifications/broadcast', input), onSuccess: () => { setForm(blankNotification); void queryClient.invalidateQueries({ queryKey: ['admin-notifications'] }); void queryClient.invalidateQueries({ queryKey: ['admin-summary'] }); } });
  if (query.isLoading) return <PageSkeleton />;
  if (query.isError || !query.data) return <ErrorState message="Không thể tải lịch sử thông báo." retry={() => void query.refetch()} />;
  return <div className="page-stack admin-notifications-page"><AdminNav /><PageHeader eyebrow="TRUNG TÂM THÔNG BÁO" title="Gửi thông báo" description="Gửi nhắc học tập hoặc thông tin vận hành tới đúng nhóm người dùng." action={<Badge tone="orange">{query.data.total} thông báo</Badge>} /><div className="admin-notification-layout"><Card className="admin-form-card"><div className="admin-panel-header"><div><div className="card-overline">THÔNG BÁO MỚI</div><h2>Soạn nội dung</h2></div><Megaphone size={21} color="var(--primary)" /></div><form className="admin-form-stack" onSubmit={(event) => { event.preventDefault(); mutation.mutate(form); }}><label>Tiêu đề<input required value={form.title} onChange={(event) => setForm((current) => ({ ...current, title: event.target.value }))} placeholder="Ví dụ: Bài luyện HSK 3 đã sẵn sàng" /></label><label>Nội dung<textarea required value={form.body} onChange={(event) => setForm((current) => ({ ...current, body: event.target.value }))} rows={6} placeholder="Viết thông tin ngắn gọn, rõ ràng cho người học…" /></label><label>Đối tượng<select value={form.audience} onChange={(event) => setForm((current) => ({ ...current, audience: event.target.value as NotificationForm['audience'] }))}><option value="ALL">Tất cả người dùng</option><option value="STUDENTS">Học viên</option><option value="TEACHERS">Giáo viên</option><option value="ADMINS">Quản trị viên</option></select></label><label>Loại thông báo<select value={form.type} onChange={(event) => setForm((current) => ({ ...current, type: event.target.value }))}><option value="ANNOUNCEMENT">Thông báo chung</option><option value="REVIEW">Nhắc ôn tập</option><option value="COURSE">Khóa học</option><option value="SYSTEM">Hệ thống</option></select></label><Button type="submit" loading={mutation.isPending}><Send size={16} /> Gửi thông báo</Button>{mutation.isSuccess && <div className="admin-feedback success"><CheckCircle2 size={16} /> Đã gửi thông báo tới người dùng phù hợp.</div>}{mutation.isError && <div className="admin-feedback error">Không thể gửi thông báo. Vui lòng thử lại.</div>}</form></Card><Card className="admin-history-card"><div className="admin-panel-header"><div><div className="card-overline">LỊCH SỬ GẦN ĐÂY</div><h2>Thông báo đã gửi</h2></div><Bell size={20} color="var(--muted)" /></div>{query.data.items.length ? <div className="admin-notification-history">{query.data.items.map((item) => <div className="admin-history-row" key={item.id}><span className="notification-icon"><Bell size={16} /></span><div><strong>{item.title}</strong><p>{item.body}</p><small>{item.user.name} · {formatDate(item.createdAt)} · {item.type}</small></div></div>)}</div> : <EmptyState icon="⌁" title="Chưa có thông báo" description="Thông báo bạn gửi sẽ xuất hiện ở đây." />}</Card></div></div>;
}

export function AdminVocabularyPage() { return <AdminHskPage />; }
export function AdminStatisticsPage() { return <AdminPage />; }
export function AdminPlaceholderPage({ title: _title }: { title: string }) { return <AdminPage />; }
